p=root/'app.js';js=p.read_text(encoding='utf-8');m=re.search(r'const guides=(\[.*?\]);',js,re.S);g=json.loads(m[1]);g[10]='Registrar conserva hechos concretos y explica cómo usarlos para una creación posterior. '+' '.join(f'{t}. Observamos: {o} Para idear: {u}'for t,o,u in items)+' Estas son posibilidades de exploración, no ideas publicitarias ya resueltas ni efectos demostrados del alcohol.';js=js[:m.start()]+'const guides='+json.dumps(g,ensure_ascii=False)+';'+js[m.end():];p.write_text(js,encoding='utf-8')
